1	package registry
2	
3	import (
4		"context"
5		"fmt"
6		"io"
7	
8		"github.com/immuta/operations/services/crow/pkg/api"
9		"github.com/immuta/operations/services/crow/pkg/client"
10		"golang.org/x/sync/errgroup"
11	)
12	
13	// Registry composes a typed Crow client with a Cache. Fetch is cache-first;
14	// FetchPair fans Fetch out concurrently with shared cancellation.
15	type Registry struct {
16		client *client.Client
17		cache  Cache
18	}
19	
20	// New constructs a Registry. Both arguments must be non-nil.
21	func New(c *client.Client, cache Cache) *Registry {
22		return &Registry{client: c, cache: cache}
23	}
24	
25	// Fetch returns the gzipped tarball bytes for the given module version,
26	// consulting the cache first. Network errors and 404s from the
27	// underlying client surface unchanged (callers can errors.Is against
28	// client.ErrNotFound).
29	func (r *Registry) Fetch(ctx context.Context, m api.Module) ([]byte, error) {
30		if body, hit, err := r.cache.Get(m); err != nil {
31			return nil, fmt.Errorf("cache get: %w", err)
32		} else if hit {
33			return body, nil
34		}
35		rc, err := r.client.Download(ctx, m)
36		if err != nil {
37			return nil, err
38		}
39		defer rc.Close()
40		body, err := io.ReadAll(rc)
41		if err != nil {
42			return nil, fmt.Errorf("read tarball: %w", err)
43		}
44		if err := r.cache.Put(m, body); err != nil {
45			// Cache write failure is not fatal — we still have the body to return.
46			_ = err
47		}
48		return body, nil
49	}
50	
51	// FetchPair fetches a and b concurrently. The first error cancels its
52	// sibling via errgroup.WithContext.
53	func (r *Registry) FetchPair(ctx context.Context, a, b api.Module) ([]byte, []byte, error) {
54		g, gctx := errgroup.WithContext(ctx)
55		var aBytes, bBytes []byte
56		g.Go(func() error {
57			body, err := r.Fetch(gctx, a)
58			if err != nil {
59				return err
60			}
61			aBytes = body
62			return nil
63		})
64		g.Go(func() error {
65			body, err := r.Fetch(gctx, b)
66			if err != nil {
67				return err
68			}
69			bBytes = body
70			return nil
71		})
72		if err := g.Wait(); err != nil {
73			return nil, nil, err
74		}
75		return aBytes, bBytes, nil
76	}
77

1	package diff
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7	
8		"github.com/hexops/gotextdiff"
9		"github.com/hexops/gotextdiff/myers"
10		"github.com/hexops/gotextdiff/span"
11	
12		"github.com/immuta/operations/apps/birdseye/internal/archive"
13	)
14	
15	// Textual returns a FileDiff per file that differs between a and b,
16	// sorted by path. Files identical in both archives are not included.
17	func Textual(a, b archive.Module) []FileDiff {
18		all := make(map[string]struct{})
19		for k := range a.Files {
20			all[k] = struct{}{}
21		}
22		for k := range b.Files {
23			all[k] = struct{}{}
24		}
25		paths := make([]string, 0, len(all))
26		for k := range all {
27			paths = append(paths, k)
28		}
29		sort.Strings(paths)
30	
31		out := make([]FileDiff, 0, len(paths))
32		for _, p := range paths {
33			ab, aok := a.Files[p]
34			bb, bok := b.Files[p]
35			switch {
36			case aok && bok:
37				if string(ab) == string(bb) {
38					continue
39				}
40				out = append(out, modifiedDiff(p, string(ab), string(bb)))
41			case !aok && bok:
42				out = append(out, addedDiff(p, string(bb)))
43			case aok && !bok:
44				out = append(out, removedDiff(p, string(ab)))
45			}
46		}
47		return out
48	}
49	
50	func modifiedDiff(path, oldText, newText string) FileDiff {
51		edits := myers.ComputeEdits(span.URIFromPath(path), oldText, newText)
52		unified := gotextdiff.ToUnified(path, path, oldText, edits)
53		u := fmt.Sprintf("%v", unified)
54		adds, dels := countLines(u)
55		return FileDiff{Path: path, Status: StatusModified, Unified: u, Adds: adds, Dels: dels}
56	}
57	
58	func addedDiff(path, newText string) FileDiff {
59		return FileDiff{
60			Path:    path,
61			Status:  StatusAdded,
62			Unified: "+++ " + path + "\n" + prefixLines(newText, "+"),
63			Adds:    countNonEmptyLines(newText),
64		}
65	}
66	
67	func removedDiff(path, oldText string) FileDiff {
68		return FileDiff{
69			Path:    path,
70			Status:  StatusRemoved,
71			Unified: "--- " + path + "\n" + prefixLines(oldText, "-"),
72			Dels:    countNonEmptyLines(oldText),
73		}
74	}
75	
76	func prefixLines(s, prefix string) string {
77		if s == "" {
78			return ""
79		}
80		lines := strings.Split(strings.TrimRight(s, "\n"), "\n")
81		var sb strings.Builder
82		sb.Grow(len(s) + len(lines)*len(prefix))
83		for _, l := range lines {
84			sb.WriteString(prefix)
85			sb.WriteString(l)
86			sb.WriteByte('\n')
87		}
88		return sb.String()
89	}
90	
91	func countNonEmptyLines(s string) int {
92		if s == "" {
93			return 0
94		}
95		n := strings.Count(s, "\n")
96		if !strings.HasSuffix(s, "\n") {
97			n++
98		}
99		return n
100	}
101	
102	func countLines(unified string) (adds, dels int) {
103		for _, line := range strings.Split(unified, "\n") {
104			if len(line) == 0 {
105				continue
106			}
107			switch line[0] {
108			case '+':
109				if !strings.HasPrefix(line, "+++") {
110					adds++
111				}
112			case '-':
113				if !strings.HasPrefix(line, "---") {
114					dels++
115				}
116			}
117		}
118		return adds, dels
119	}
