1	package api
2	
3	import (
4		"fmt"
5		"regexp"
6		"strings"
7	)
8	
9	// segmentRegex matches a single path segment: starts with alphanumeric,
10	// followed by alphanumeric, dots, underscores, or hyphens. It is the single
11	// source of truth for segment validation — the Crow server and its clients
12	// both import this package so they cannot drift.
13	var segmentRegex = regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9._-]*$`)
14	
15	// versionSemverRegex is the SemVer 2.0.0 grammar from semver.org, minus the
16	// build metadata suffix. Two intentional deviations from the spec:
17	//   - No leading 'v' allowed. Terraform's native module loader strips the
18	//     prefix when building download URLs (per hashicorp/go-version
19	//     normalization), while terragrunt's tfr:// passes the version through
20	//     verbatim. A v-prefixed version uploaded today would resolve via
21	//     terragrunt and 404 via terraform — failing fast on upload prevents
22	//     the divergence.
23	//   - No '+build.metadata' suffix allowed. segmentRegex above doesn't
24	//     permit '+', so a build-tagged version couldn't be served from the
25	//     URL even if we accepted it on upload.
26	var versionSemverRegex = regexp.MustCompile(`^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?$`)
27	
28	type InvalidSegmentError struct {
29		Segment string
30	}
31	
32	func (e InvalidSegmentError) Error() string {
33		return fmt.Sprintf("invalid segment %q: must match %s", e.Segment, segmentRegex)
34	}
35	
36	// InvalidVersionError is returned when a version string is not valid SemVer
37	// 2.0.0 (no leading 'v', no '+build' metadata).
38	type InvalidVersionError struct {
39		Version string
40	}
41	
42	func (e InvalidVersionError) Error() string {
43		return fmt.Sprintf("invalid version %q: expected bare SemVer 2.0.0 (e.g. \"1.2.3\", \"1.2.3-rc.1\") per https://semver.org", e.Version)
44	}
45	
46	// ValidateSegments returns an InvalidSegmentError for the first segment that
47	// fails the regex. An empty slice passes.
48	func ValidateSegments(segments []string) error {
49		for _, s := range segments {
50			if !segmentRegex.MatchString(s) {
51				return InvalidSegmentError{Segment: s}
52			}
53		}
54		return nil
55	}
56	
57	// ValidateVersion enforces SemVer 2.0.0 on a module version string. It is
58	// applied at upload boundaries (server handler + client) so non-semver
59	// versions can't enter storage. Download/list paths intentionally don't
60	// call this so that any v-prefixed versions still in S3 from before the
61	// guard remain reachable.
62	func ValidateVersion(version string) error {
63		if !versionSemverRegex.MatchString(version) {
64			return InvalidVersionError{Version: version}
65		}
66		return nil
67	}
68	
69	func (id ModuleIdentifier) Validate() error {
70		return ValidateSegments([]string{id.Namespace, id.Name, id.Provider})
71	}
72	
73	func (id ModuleIdentifier) VersionsPath() string {
74		return "/v1/modules/" + strings.Join([]string{id.Namespace, id.Name, id.Provider}, "/") + "/versions"
75	}
